import * as s from "../../core/validation/index.js";
import type { Schema } from "../../core/validation/schema.js";
import {
  responsesCustomToolCallOutputContentSchema,
  type ResponsesCustomToolCallOutputContent,
} from "./responses-custom-tool-call-output-content.js";

/**
 * Text or image output of the custom tool call generated by your code. Can be a string of the
 * output, or an array of content parts (text or image).
 */
export type Output1 = string | ResponsesCustomToolCallOutputContent[];

export const output1Schema: Schema<Output1> = s.of<Output1>(
  s.union([s.string(), s.array(s.lazy(() => responsesCustomToolCallOutputContentSchema))]),
);
